import { GENERATED_SKILLS, GENERATED_CATEGORIES } from '../generated/skills';

export type ModeId = 'ask' | 'edit' | 'agent' | 'debug' | 'review';

export interface ModeEntry {
  id: ModeId;
  label: string;
  icon: LucideIcon;
  description: string;
  color: string;
  shortcut: string;
}

